D=$SC/bizhawk/data_$5; mkdir -p $D; cp -n $SC/bizhawk/data/{ages.gbc,ages.bk2,config.ini,anchors.lua} $D/ 2>/dev/null; cp -Rn $SC/bizhawk/data/Firmware $SC/bizhawk/data/dll-arm64 $D/ 2>/dev/null
